parameters.jsCode:
// ===== utilitários padrão Konext (iguais em todos os fluxos) =====
const n_ = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]/g, '');
const pick = (row, nomes) => {
  const m = {};
  for (const k of Object.keys(row || {})) m[n_(k)] = row[k];
  for (const nome of nomes) { const v = m[n_(nome)]; if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim(); }
  return '';
};
const dig = v => String(v ?? '').replace(/\D/g, '');
const sim = (v, padrao) => { const t = n_(v); if (!t) return padrao; return ['sim', 's', 'yes', 'y', 'true', '1', 'ativo'].includes(t); };
const nao = v => ['nao', 'n', 'no', 'false', '0', 'inativo'].includes(n_(v));
const money = v => {
  let s = String(v ?? '').replace(/[^\d,.\-]/g, '');
  if (!s) return null;
  const c = s.lastIndexOf(','), p = s.lastIndexOf('.');
  if (c > -1 && p > -1) s = c > p ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '');
  else if (c > -1) s = s.replace(',', '.');
  else if (/^\d{1,3}(\.\d{3})+$/.test(s)) s = s.replace(/\./g, '');
  const n = parseFloat(s); return isNaN(n) ? null : n;
};
// Número de WhatsApp ou ID de grupo -> formato aceito pela Evolution API
const jid = v => {
  const s = String(v ?? '').trim();
  if (!s) return '';
  if (/@g\.us$/i.test(s)) return s.replace(/\s/g, '');
  const d = s.replace(/\D/g, '');
  if (!d) return '';
  if (d.startsWith('120363') && d.length >= 15) return d + '@g.us';
  return d.length <= 11 ? '55' + d : d;
};

const cfg = $('Config (CPR)').first().json;
const preferirGrupo = !(cfg.preferir_grupo === false || cfg.preferir_grupo === 'false');
const grupos = $('Grupos WhatsApp (CPR)').all().map(i => i.json || {}).filter(g => !g.error)
  .map(g => ({ nome: pick(g, ['Grupo', 'Nome do Grupo', 'Nome']), id: pick(g, ['ID', 'ID do Grupo']).replace(/\s/g, ''), ativo: !nao(pick(g, ['Ativo'])) }))
  .filter(g => g.ativo && /@g\.us$/i.test(g.id))
  .map(g => ({ ...g, chave: n_(g.nome) }));
// Procura o grupo do cliente pelo nome / apelidos (só aceita quando há UM grupo compatível)
const acharGrupo = (cliente, apelidos) => {
  const cands = [cliente, ...apelidos].map(n_).filter(c => c.length >= 4);
  let m = grupos.filter(g => cands.some(c => g.chave.includes(c)));
  if (m.length === 1) return m[0];
  if (m.length > 1) return null;
  const primeiro = n_(String(cliente).trim().split(/\s+/)[0]);
  if (primeiro.length >= 4) { m = grupos.filter(g => g.chave.includes(primeiro)); if (m.length === 1) return m[0]; }
  return null;
};
// Destino: grupo do cliente (coluna "ID do Grupo" ou planilha de grupos) e, se não houver, o "Contato do cliente".
// O "Contato do cliente" também pode conter direto um ID de grupo (120363...@g.us).
const montarDestino = (cliente, apelidos, contatoRaw, grupoRaw) => {
  const contato = jid(contatoRaw);
  const fixo = jid(grupoRaw);
  const g = fixo.endsWith('@g.us') ? { id: fixo, nome: '(ID do Grupo na planilha)' } : acharGrupo(cliente, apelidos);
  let destino = '', destino_desc = '';
  const porGrupo = () => { destino = g.id; destino_desc = 'grupo ' + g.nome; };
  const porContato = () => { destino = contato; destino_desc = (contato.endsWith('@g.us') ? 'grupo ' : 'WhatsApp ') + contato; };
  if (preferirGrupo) { if (g) porGrupo(); else if (contato) porContato(); }
  else { if (contato) porContato(); else if (g) porGrupo(); }
  return { contato, grupo: g ? g.id : '', grupo_nome: g ? g.nome : '', destino, destino_desc };
};
const clientes = []; const vistos = new Set();
for (const it of $('Clientes Geral (CPR)').all()) {
  const r = it.json || {};
  if (r.error) continue;
  if (!sim(pick(r, ['Status', 'Ativo']), false)) continue;           // Status = Ativo
  const conta = dig(pick(r, ['ID da Conta', 'Conta de Anuncio', 'Conta de Anúncio', 'Conta']));
  const cliente = pick(r, ['Cliente', 'Clientes', 'Nome do cliente', 'Nome']);
  if (!conta || vistos.has(conta)) continue;
  vistos.add(conta);
  const apelidos = pick(r, ['Apelido', 'Apelidos']).split(',').map(s => s.trim()).filter(Boolean);
  clientes.push({
    row_number: r.row_number, cliente: cliente || ('Conta ' + conta), conta, apelidos,
    ...montarDestino(cliente, apelidos, pick(r, ['Contato do cliente', 'Contato', 'WhatsApp do cliente', 'Telefone']), pick(r, ['ID do Grupo', 'Grupo WhatsApp', 'Grupo do cliente'])),
    valor_base: money(pick(r, ['Valor Base'])),
    reativar: sim(pick(r, ['Reativar na Segunda', 'Reativar toda segunda', 'Reativar toda segunda-feira', 'Reativar']), true),
    monitorar: sim(pick(r, ['Monitorar Custo']), true),
    pagina: dig(pick(r, ['ID da Página', 'ID da Pagina'])),
    ig_id: dig(pick(r, ['ID Instagram', 'ID do Instagram'])),
    ig_user: pick(r, ['Instagram (usuário)', 'Usuário do Instagram', 'Instagram']).replace(/^@/, ''),
    whatsapp_campanha: jid(pick(r, ['WhatsApp da Campanha', 'WhatsApp'])),
    link_relatorio: pick(r, ['Link do Relatório', 'Link do Relatorio', 'Link Relatório', 'Relatório', 'Link do Dashboard']),
    enviar_relatorio: sim(pick(r, ['Enviar Relatório', 'Enviar Relatorio']), true),
    rel_melhorias: pick(r, ['Relatório - Melhorias', 'Melhorias']),
    rel_ajustes: pick(r, ['Relatório - Ajustes', 'Ajustes']),
  });
}

return clientes.filter(c => c.monitorar).map(c => ({ json: c }));

const cfg = $('Config (CPR)').first().json;
const cli = $('Loop Clientes (CPR)').item.json;
const idConta = String(cli.conta);
const num = v => { const n = parseFloat(v); return isNaN(n) ? 0 : n; };
const erroDe = r => {
  if (!r) return 'sem resposta';
  if (r.error || !Array.isArray(r.data)) {
    let e = r.error;
    if (e && typeof e === 'object') e = e.message || JSON.stringify(e);
    return String(e ?? JSON.stringify(r)).slice(0, 250);
  }
  return null;
};
const teste = cfg.modo_teste === true || cfg.modo_teste === 'true';

// --- controle de alertas repetidos (memória do workflow; só persiste com o workflow ativo)
const sd = $getWorkflowStaticData('global');
sd.alertas = sd.alertas || {};
const agora = Date.now();
const janelaMs = num(cfg.reaviso_horas) * 3600 * 1000;
for (const k of Object.keys(sd.alertas)) if (agora - sd.alertas[k] > 48 * 3600 * 1000) delete sd.alertas[k];
const pode = k => !sd.alertas[k] || (agora - sd.alertas[k]) > janelaMs;

const base = { cliente: cli.cliente, id_conta: idConta, destino: cli.destino, destino_desc: cli.destino_desc, mensagem_erro: '', violacoes: [] };
// campanhas pausadas pelo monitor e reativadas manualmente ficam liberadas por um tempo
sd.cpr_pausadas = sd.cpr_pausadas || {};
for (const k of Object.keys(sd.cpr_pausadas)) if (agora - sd.cpr_pausadas[k] > 72 * 3600 * 1000) delete sd.cpr_pausadas[k];
const liberadaMs = num(cfg.ignorar_apos_reativacao_horas) * 3600 * 1000;

const rSets = $('Conjuntos Ativos (CPR)').first().json;
const r3 = $('Insights Curto (CPR)').first().json;
const r15 = $input.item.json;

const falhas = [['conjuntos', rSets], ['insights curto', r3], ['insights longo', r15]]
  .map(([n, r]) => { const e = erroDe(r); return e ? `${n}: ${e}` : null; }).filter(Boolean);
if (falhas.length) {
  const k = 'erro:' + idConta;
  if (!pode(k)) return { json: { ...base, acao: 'nada' } };
  sd.alertas[k] = agora;
  return { json: { ...base, acao: 'erro', mensagem_erro: falhas.join(' | ').slice(0, 600) } };
}

// --- campanhas ativas + tipo, a partir dos conjuntos ativos (conjunto ativo => campanha ativa)
const goals = {}, nomes = {};
for (const s of rSets.data) {
  (goals[s.campaign_id] = goals[s.campaign_id] || new Set()).add(s.optimization_goal);
  nomes[s.campaign_id] = (s.campaign && s.campaign.name) || s.campaign_id;
}
const TIPOS = {
  mensagens: { nome: 'Mensagens', resultado: 'Conversas iniciadas', meta: num(cfg.cpr_msg_meta), max: num(cfg.cpr_msg_max), gastoMin: num(cfg.gasto_min_sem_resultado_msg) },
  visitas:   { nome: 'Visitas ao perfil', resultado: 'Visitas ao perfil', meta: null, max: num(cfg.cpr_visita_max), gastoMin: num(cfg.gasto_min_sem_resultado_visita) },
};
const tipoDe = id => {
  const g = goals[id]; if (!g) return null;
  if (g.has('CONVERSATIONS')) return 'mensagens';
  if (g.has('VISIT_INSTAGRAM_PROFILE')) return 'visitas';
  return null;
};
const resultOf = (actions, tipo) => {
  if (!Array.isArray(actions)) return 0;
  const hit = actions.find(x => tipo === 'mensagens'
    ? x.action_type === cfg.acao_mensagens
    : (x.action_type === cfg.acao_visitas || /profile_visit/i.test(x.action_type)));
  return hit ? num(hit.value) : 0;
};
const por = arr => Object.fromEntries(arr.map(i => [i.campaign_id, i]));
const m3 = por(r3.data), m15 = por(r15.data);

const dCurta = num(cfg.janela_curta_dias), dLonga = num(cfg.janela_longa_dias);
const fmt = d => $now.minus({ days: d }).toFormat('dd/MM');
const violacoes = [];
for (const [campId, campNome] of Object.entries(nomes)) {
  const tipo = tipoDe(campId); if (!tipo) continue;
  if (!teste && sd.cpr_pausadas[campId] && (agora - sd.cpr_pausadas[campId]) < liberadaMs) continue; // reativada manualmente
  const t = TIPOS[tipo];
  const i3 = m3[campId]; if (!i3) continue;
  const i15 = m15[campId] || {};
  const spend3 = num(i3.spend), res3 = resultOf(i3.actions, tipo);
  const cpr3 = res3 > 0 ? spend3 / res3 : null;
  let violou = false, codigo = '';
  if (res3 > 0 && cpr3 > t.max) { violou = true; codigo = 'cpr_acima'; }
  else if (res3 === 0 && spend3 >= t.gastoMin) { violou = true; codigo = 'sem_resultado'; }
  if (!violou) continue;
  // Modo real: sem limite de repetição (se a pausa falhar, tenta de novo na próxima rodada).
  // Modo teste: limita a 1 aviso por campanha a cada "reaviso_horas", para não lotar o WhatsApp.
  if (teste) {
    const k = 'teste:camp:' + campId;
    if (!pode(k)) continue;
    sd.alertas[k] = agora;
  }
  const spend15 = num(i15.spend), res15 = resultOf(i15.actions, tipo);
  violacoes.push({
    campanha_id: campId, campanha_nome: campNome, tipo, tipo_nome: t.nome, resultado_nome: t.resultado,
    limite_meta: t.meta, limite_max: t.max, gasto_min: t.gastoMin, codigo,
    spend3, res3, cpr3, imp3: num(i3.impressions), reach3: num(i3.reach), freq3: num(i3.frequency),
    spend15, res15, cpr15: res15 > 0 ? spend15 / res15 : null,
    imp15: num(i15.impressions), reach15: num(i15.reach), freq15: num(i15.frequency),
    d_curta: dCurta, d_longa: dLonga,
    desde_curta: fmt(dCurta - 1), desde_longa: fmt(dLonga - 1), ate: fmt(0),
  });
}
if (!violacoes.length) return { json: { ...base, acao: 'nada' } };
return { json: { ...base, acao: 'pausar', violacoes } };

