parameters.jsCode:
const cfg = $('Config (CPR)').first().json;
const src = $('Separar Violações').item.json;
const v = src.violacoes;
const act = src.id_conta;
const num = x => { const n = parseFloat(x); return isNaN(n) ? 0 : n; };
const milhar = s => s.replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const brl = n => 'R$ ' + milhar(n.toFixed(2).replace('.', ','));
const int = n => milhar(Math.round(n).toString());
const dec = n => n.toFixed(2).replace('.', ',');
const cprTxt = n => (n === null || n === undefined) ? 'sem resultados' : brl(n);

let pausa = null;
try { pausa = $('Pausar Campanha (CPR)').item.json; } catch (e) {}
const simulacao = cfg.modo_teste === true || cfg.modo_teste === 'true';
let status;
if (simulacao) status = '🧪 SIMULAÇÃO — nada foi pausado (modo de teste ligado)';
else if (pausa && (pausa.success === true || pausa.success === 'true')) status = '⏸️ Campanha PAUSADA com sucesso';
else {
  let e = pausa && pausa.error; if (e && typeof e === 'object') e = e.message || JSON.stringify(e);
  status = '❌ FALHA AO PAUSAR — pause manualmente! ' + String(e ?? '').slice(0, 200);
}

const limiteTxt = v.limite_meta !== null
  ? `meta ${brl(v.limite_meta)} / máximo tolerado ${brl(v.limite_max)}`
  : `limite ${brl(v.limite_max)}`;
const motivo = v.codigo === 'cpr_acima'
  ? `O custo por resultado dos últimos ${v.d_curta} dias (*${brl(v.cpr3)}*) ficou acima do máximo permitido (${limiteTxt}).`
  : `A campanha investiu *${brl(v.spend3)}* nos últimos ${v.d_curta} dias sem nenhum resultado (limite sem resultado: ${brl(v.gasto_min)}).`;

const bloco = (titulo, de, imp, reach, freq, res, cpr, spend) =>
`📊 *${titulo}* (${de} a ${v.ate})
• Impressões: ${int(imp)}
• Alcance: ${int(reach)}
• Frequência: ${dec(freq)}
• Resultados (${v.resultado_nome}): ${int(res)}
• Custo por resultado: ${cprTxt(cpr)}
• Investido: ${brl(spend)}`;

// anúncios
const ins = Array.isArray($('Insights dos Anúncios').item.json.data) ? $('Insights dos Anúncios').item.json.data : [];
const info = Array.isArray($input.item.json.data) ? $input.item.json.data : [];
const infoPorId = Object.fromEntries(info.map(a => [a.id, a]));
const resultOf = actions => {
  if (!Array.isArray(actions)) return 0;
  const hit = actions.find(x => v.tipo === 'mensagens'
    ? x.action_type === cfg.acao_mensagens
    : (x.action_type === cfg.acao_visitas || /profile_visit/i.test(x.action_type)));
  return hit ? num(hit.value) : 0;
};
const ads = ins.map(i => {
  const spend = num(i.spend), res = resultOf(i.actions);
  return { id: i.ad_id, nome: i.ad_name, spend, res, cpr: res > 0 ? spend / res : null, imp: num(i.impressions), prev: (infoPorId[i.ad_id] || {}).preview_shareable_link };
}).sort((x, y) => y.spend - x.spend);

const TOP = 8;
const linhasAds = ads.slice(0, TOP).map((ad, n) => {
  let t = `${n + 1}) *${ad.nome}*\n   🆔 ${ad.id}\n   💰 ${brl(ad.spend)} | 🎯 ${int(ad.res)} resultado(s) | CPR: ${cprTxt(ad.cpr)}\n   🔗 https://adsmanager.facebook.com/adsmanager/manage/ads?act=${act}&selected_ad_ids=${ad.id}`;
  if (ad.prev) t += `\n   👁️ Prévia: ${ad.prev}`;
  return t;
});
if (ads.length > TOP) linhasAds.push(`… e mais ${ads.length - TOP} anúncio(s) com entrega no período.`);

const cab = simulacao ? '🧪 *SIMULAÇÃO — esta campanha SERIA pausada*' : '🚨 *CAMPANHA PAUSADA — custo por resultado acima do limite*';
let msg = `${cab}

👤 *Cliente:* ${src.cliente}
📣 *Campanha:* ${v.campanha_nome}
🆔 *ID:* ${v.campanha_id}
🎯 *Tipo / resultado:* ${v.tipo_nome} → ${v.resultado_nome}
🔗 https://adsmanager.facebook.com/adsmanager/manage/campaigns?act=${act}&selected_campaign_ids=${v.campanha_id}

📌 *Por que:* ${motivo}

${bloco('Últimos ' + v.d_curta + ' dias', v.desde_curta, v.imp3, v.reach3, v.freq3, v.res3, v.cpr3, v.spend3)}

${bloco('Últimos ' + v.d_longa + ' dias', v.desde_longa, v.imp15, v.reach15, v.freq15, v.res15, v.cpr15, v.spend15)}

${status}

🎨 *Anúncios com entrega nos últimos ${v.d_curta} dias:*
${linhasAds.length ? linhasAds.join('\n\n') : '(nenhum anúncio com entrega encontrado)'}`;
if (msg.length > 3900) msg = msg.slice(0, 3850) + '\n… (mensagem cortada)';

// memória: pausada pelo monitor (para não repausar se você reativar manualmente) e controle de alertas de falha
const sd = $getWorkflowStaticData('global');
sd.cpr_pausadas = sd.cpr_pausadas || {}; sd.alertas = sd.alertas || {};
const pausaOk = !simulacao && pausa && (pausa.success === true || pausa.success === 'true');
let enviar = true;
if (pausaOk) sd.cpr_pausadas[v.campanha_id] = Date.now();
else if (!simulacao) {
  const k = 'falha:' + v.campanha_id;
  if (sd.alertas[k] && (Date.now() - sd.alertas[k]) < Number(cfg.reaviso_horas) * 3600 * 1000) enviar = false;
  else sd.alertas[k] = Date.now();
}
const motivoCurto = v.codigo === 'cpr_acima'
  ? `Custo por resultado ${brl(v.cpr3)} acima do máximo ${brl(v.limite_max)} (${v.d_curta} dias)`
  : `${brl(v.spend3)} investidos sem resultado em ${v.d_curta} dias`;
const linksAds = ads.slice(0, 8).map(ad => ad.prev || `https://adsmanager.facebook.com/adsmanager/manage/ads?act=${act}&selected_ad_ids=${ad.id}`).join(' ');
return { json: { mensagem: msg, enviar, simulacao, pausa_ok: pausaOk, destino: src.destino || '', destino_desc: src.destino_desc || '', cliente: src.cliente,
  id_conta: String(act), campanha_id: String(v.campanha_id), campanha_nome: v.campanha_nome, motivo_curto: motivoCurto, links_anuncios: linksAds } };

const cfg = $('Config (CPR)').first().json;
const gestor = String(cfg.numero_gestor);
const avisarCliente = !(cfg.avisar_cliente === false || cfg.avisar_cliente === 'false');
const envios = [];
for (const it of $input.all()) {
  const m = it.json || {};
  if (!m.enviar) continue;
  if (avisarCliente && !m.simulacao && m.destino) envios.push({ para: m.destino, texto: m.mensagem });
  let nota = '';
  if (!m.simulacao) nota = m.destino ? (avisarCliente ? `\n\n📨 Aviso enviado ao cliente: ${m.destino_desc}` : '') : '\n\n📵 Cliente sem grupo e sem "Contato do cliente" na Planilha Geral — o cliente NÃO foi avisado.';
  if (m.destino !== gestor || m.simulacao) envios.push({ para: gestor, texto: (m.mensagem + nota).slice(0, 4000) });
}
return envios.length ? envios.map(e => ({ json: e })) : [{ json: { skip: true } }];

// registro de cada campanha pausada pelo monitor (lido pelo Relatório de Performance)
return $input.all().map(i => i.json || {}).filter(m => m.pausa_ok).map(m => ({ json: {
  'Data': $now.toFormat('dd/MM/yyyy HH:mm'), 'Cliente': m.cliente, 'ID da Conta': m.id_conta,
  'ID Campanha': m.campanha_id, 'Nome Campanha': m.campanha_nome, 'Motivo': m.motivo_curto, 'Anúncios': m.links_anuncios } }));
